<script setup>import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import PageHeader from'../../Components/PageHeader.vue';import UiButton from'../../Components/UiButton.vue';import{Head,Link}from'@inertiajs/vue3';defineProps({groups:Array})</script>
<template><AppShell><Head title="Groups"/><div class="lp-page"><PageHeader eyebrow="Groups" title="Photo-sharing projects" description="Each Group contains one project’s gallery, participants, privacy, face matching and delivery operations."><UiButton href="/groups/create">Create Group</UiButton></PageHeader><StateCard v-if="!groups.length" class="mt-8" title="Create your first Group" message="Start a wedding, function, conference or photoshoot workspace."><UiButton href="/groups/create" class="mt-5">Create Group</UiButton></StateCard><div v-else class="mt-8 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="group in groups" :key="group.id" class="lp-card lp-card-hover overflow-hidden"><div class="h-40 bg-gradient-to-tr from-ink to-indigo"><img v-if="group.cover_url" :src="group.cover_url" alt="" class="h-full w-full object-cover"></div><div class="p-5"><div class="flex justify-between gap-3"><h2 class="text-lg font-bold">{{group.name}}</h2><span class="lp-badge-success">{{group.is_active?'Active':'Archived'}}</span></div><p class="mt-2 text-sm text-slate-600">{{group.event_type||'Project'}} · {{group.photos_count}} photos · {{group.members_count}} participants</p><p class="mt-2 text-xs text-slate-500">Updated {{new Date(group.updated_at).toLocaleDateString()}}</p><div class="mt-5 flex flex-wrap gap-2"><Link :href="`/groups/${group.id}`" class="btn-primary">Open Group</Link><Link :href="`/groups/${group.id}/settings`" class="btn-secondary">Settings</Link></div></div></article></div></div></AppShell></template>
